// Interface between the runtime and the statically recompiled game code
// (generated by tools/recomp.py at build time).
#pragma once

#include "m68k/cpu.hpp"

#include <cstddef>
#include <cstdint>

namespace recomp {

// Executes recompiled code starting at cpu.pc until control leaves the
// compiled region or cpu.cycles >= deadline; cpu.pc is always left pointing
// at the next instruction to execute.
using Fn = void (*)(m68k::Cpu&, int64_t deadline);

struct Entry {
  uint32_t addr;
  Fn fn;
};

struct Image {
  const Entry* entries;
  size_t count;
  uint32_t base;       // first address covered
  uint32_t size;       // bytes covered
  uint32_t checksum;   // FNV-1a of the (patched) image the code was built from
};

// Provided by the generated code; returns nullptr when the build has no
// recompiled code.
const Image* image();

}  // namespace recomp
